    const QRectF chart(35,292,(width-82)*.52,245),overview(chart.right()+16,292,width-chart.right()-51,245); rounded(painter,chart,Qt::white,12,line); rounded(painter,overview,Qt::white,12,line); setFont(painter,13,QFont::Bold,navy); painter.drawText(chart.adjusted(18,15,-18,-195),Qt::AlignLeft|Qt::AlignVCenter,"Operational status overview"); setFont(painter,8,QFont::Normal,muted); painter.drawText(chart.adjusted(18,38,-18,-170),Qt::AlignLeft|Qt::AlignVCenter,"Status counts are calculated from the current equipment inventory."); const QStringList statusLabels{"Online","Offline","Maintenance"}; const qreal maximum=qMax(1,qMax(statuses["Online"],qMax(statuses["Offline"],statuses["Maintenance"]))); for(int i=0;i<statusLabels.size();++i) { const QString status=statusLabels[i]; const qreal y=chart.top()+86+i*48; setFont(painter,9,QFont::DemiBold,navy); painter.drawText(QRectF(chart.left()+20,y,98,24),Qt::AlignVCenter,status); rounded(painter,QRectF(chart.left()+122,y+4,chart.width()-190,16),QColor("#EEF3F9"),8); rounded(painter,QRectF(chart.left()+122,y+4,(chart.width()-190)*statuses[status]/maximum,16),statusColor(status),8); setFont(painter,10,QFont::Bold,statusColor(status)); painter.drawText(QRectF(chart.right()-55,y,36,24),Qt::AlignRight|Qt::AlignVCenter,QString::number(statuses[status])); }
    setFont(painter,13,QFont::Bold,navy); painter.drawText(overview.adjusted(18,15,-18,-195),Qt::AlignLeft|Qt::AlignVCenter,"Client decision support"); const QStringList advice{QString("%1 offline equipment needs reception or connection verification.").arg(statuses["Offline"]),QString("%1 equipment item%2 is in maintenance and should be followed before deployment.").arg(statuses["Maintenance"]).arg(statuses["Maintenance"]==1?"":"s"),"Use the inventory pages for stock control, traceability and replacement planning."}; qreal adviceY=overview.top()+62; for(const QString &item:advice) { rounded(painter,QRectF(overview.left()+18,adviceY,8,8),blue,4); setFont(painter,9,QFont::Normal,muted); painter.drawText(QRectF(overview.left()+38,adviceY-7,overview.width()-60,37),Qt::TextWordWrap,item); adviceY+=58; }
